'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dpstf2 = require( './../lib' );


// FUNCTIONS //

/**
* Creates a bounded reset-and-factor benchmark.
*
* @private
* @param {PositiveInteger} N - matrix order
* @param {string} uplo - stored triangle
* @param {boolean} truncated - whether to use a cutoff after the first step
* @returns {Function} benchmark function
*/
function createBenchmark( N, uplo, truncated ) {
	var original;
	var WORK;
	var RANK;
	var PIV;
	var tol;
	var A;
	var i;
	var j;

	original = new Float64Array( N*N );
	A = new Float64Array( N*N );
	WORK = new Float64Array( 2*N );
	PIV = new Int32Array( N );
	RANK = new Int32Array( 1 );
	tol = ( truncated ) ? N+2.0 : -1.0;
	for ( i = 0; i < N; i++ ) {
		for ( j = 0; j < N; j++ ) {
			if ( i === j ) {
				original[ (i*N)+j ] = N + 2.0;
			} else if ( ( uplo === 'upper' && i < j ) || ( uplo === 'lower' && i > j ) ) {
				original[ (i*N)+j ] = 0.25;
			} else {
				original[ (i*N)+j ] = 999.0;
			}
		}
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var expectedInfo;
		var expectedRank;
		var info;
		var i;

		expectedInfo = ( truncated ) ? 1 : 0;
		expectedRank = ( truncated ) ? 1 : N;
		info = 0;
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Reset the changed matrix before each factorization:
			A.set( original );
			info = dpstf2( 'row-major', uplo, N, A, N, PIV, RANK, tol, WORK );
			if ( info !== expectedInfo || RANK[ 0 ] !== expectedRank ) {
				b.fail( 'should produce the expected factorization status and rank' );
				break;
			}
		}
		b.toc();
		for ( i = 0; i < N; i++ ) {
			if ( PIV[ i ] !== i+1 ) {
				b.fail( 'should produce the complete identity permutation' );
				break;
			}
		}
		if ( ( uplo === 'upper' && A[ N ] !== 999.0 ) || ( uplo === 'lower' && A[ 1 ] !== 999.0 ) ) {
			b.fail( 'should preserve the ignored triangle' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var uplos;
	var name;
	var fcn;
	var i;
	var j;
	var k;

	options = {
		'iterations': 200,
		'repeats': 2
	};
	sizes = [ 8, 16 ];
	uplos = [ 'upper', 'lower' ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < uplos.length; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				name = format( '%s:triangle=%s:N=%d:cutoff=%s', pkg, uplos[ j ], sizes[ i ], ( k ) ? 'user' : 'default' );
				fcn = createBenchmark( sizes[ i ], uplos[ j ], k === 1 );
				bench( name, options, fcn );
			}
		}
	}
}

main();
